import 'dart:typed_data';

import 'package:dead_drop/src/fountain.dart';
import 'package:flutter_test/flutter_test.dart';

/// Fixed expected outputs of [chunkIdsFor].
///
/// These were generated by this implementation, so they do not prove it
/// is *correct* — they pin it, which is what is needed here. The chunk
/// ids are no longer transmitted (see
/// docs/decisions/0001-derive-chunk-ids-from-the-seed.md), so emitter and
/// receiver agreeing is no longer something the wire can check: a change
/// to this derivation silently corrupts every transfer between a rebuilt
/// sender and an older receiver. If a refactor changes these values, that
/// is a wire format change and must be treated as one.
const _vectors = [
  (k: 10, seed: 1, seq: 1, ids: <int>[0, 5]),
  (k: 10, seed: 1, seq: 2, ids: <int>[1, 4]),
  (k: 10, seed: 42, seq: 7, ids: <int>[0, 4]),
  (k: 100, seed: 12345, seq: 1, ids: <int>[3, 16, 30, 42, 44, 53, 72, 73, 89]),
  (k: 100, seed: 12345, seq: 50, ids: <int>[94, 97]),
  (k: 100, seed: 999, seq: 300, ids: <int>[6, 13, 29, 67, 79, 82, 83, 92, 99]),
  (k: 1000, seed: 7, seq: 1, ids: <int>[85, 100, 209, 911]),
  (
    k: 1000,
    seed: 7,
    seq: 1234,
    ids: <int>[
      5, 59, 87, 174, 189, 236, 335, 342, 429, 509, 525, 546, 568, 628,
      636, 657, 755, 760, 856, 880, 962, 984, 998,
    ],
  ),
];

void main() {
  group('chunkIdsFor', () {
    test('matches its pinned vectors', () {
      for (final v in _vectors) {
        expect(
          chunkIdsFor(seq: v.seq, seed: v.seed, k: v.k),
          v.ids,
          reason: 'k=${v.k} seed=${v.seed} seq=${v.seq}',
        );
      }
    });

    test('the vectors are not all trivially equal', () {
      // Without this, a derivation that returned a constant would satisfy
      // the test above if the vectors happened to be regenerated from it.
      final distinct = _vectors.map((v) => v.ids.join(',')).toSet();
      expect(distinct.length, _vectors.length);
      expect(_vectors.map((v) => v.ids.length).toSet().length,
          greaterThan(2));
    });

    test('the encoder uses exactly this derivation', () {
      // The property the whole change rests on: what the emitter XORs
      // into a frame is what the receiver will recompute. If these ever
      // diverge, transfers corrupt with no error anywhere.
      for (final k in [10, 100, 1000]) {
        final enc = LTEncoder(
          List.generate(k, (i) => Uint8List.fromList([i & 0xff, 0, 0, 0])),
        );
        for (final seq in [1, 2, 17, 500]) {
          expect(
            enc.makeFrame(seq, 4242).$1,
            chunkIdsFor(seq: seq, seed: 4242, k: k),
            reason: 'k=$k seq=$seq',
          );
        }
      }
    });

    test('ids are in range, sorted and distinct', () {
      for (final k in [10, 100, 1000]) {
        for (var seq = 1; seq <= 60; seq++) {
          final ids = chunkIdsFor(seq: seq, seed: 31337, k: k);
          expect(ids, isNotEmpty, reason: 'k=$k seq=$seq');
          expect(ids.toSet().length, ids.length, reason: 'k=$k seq=$seq');
          expect(ids, orderedEquals([...ids]..sort()));
          for (final id in ids) {
            expect(id, inInclusiveRange(0, k - 1));
          }
        }
      }
    });
  });
}
